INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷78·晋高祖纪·天福四年正月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d0ce37b98c182cdb5c5cd2ee909baa3b407a4785/content/books/zizhi-tongjian/vol-282/year-0939/part-01/sources/library/jiuwudaishi-078-january/source.txt", "note": "《旧五代史》卷78·晋高祖纪·天福四年正月，段落 jiu-wudaishi-205deb4a7860-p001925；已核上下文及传主，纸本及异文待核。", "id": "59f06ca9-715e-5a35-a824-c3326f5b68ff"}, {"title": "旧五代史·卷78·晋高祖纪·天福四年三月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d0ce37b98c182cdb5c5cd2ee909baa3b407a4785/content/books/zizhi-tongjian/vol-282/year-0939/part-01/sources/library/jiuwudaishi-078-march/source.txt", "note": "《旧五代史》卷78·晋高祖纪·天福四年三月，段落 jiu-wudaishi-205deb4a7860-p001929；已核上下文及传主，纸本及异文待核。", "id": "376eaf5e-c2ae-5d4f-8723-cdac07ca5ecc"}, {"title": "旧五代史·卷125·冯晖传", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d0ce37b98c182cdb5c5cd2ee909baa3b407a4785/content/books/zizhi-tongjian/vol-282/year-0939/part-01/sources/library/jiuwudaishi-125-feng-hui/source.txt", "note": "《旧五代史》卷125·冯晖传，段落 jiu-wudaishi-205deb4a7860-p002923；已核上下文及传主，纸本及异文待核。", "id": "27ab1fcc-bf2a-5c21-9a89-46f35acf160e"}, {"title": "资治通鉴·后晋纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d0ce37b98c182cdb5c5cd2ee909baa3b407a4785/content/books/zizhi-tongjian/vol-282/year-0939/part-01/sources/library/tongjian-282-939-opening/source.txt", "note": "《资治通鉴》后晋纪三，段落 zizhi-tongjian-a63549944a71-p003348；电子底本待考，分段待核", "id": "83432c9e-3ed6-5bee-a017-a2396a6d9ba8"}, {"title": "新唐书·卷80·宗室·李祎附传", "source_type": "primary", "author": "欧阳修、宋祁", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d0ce37b98c182cdb5c5cd2ee909baa3b407a4785/content/books/zizhi-tongjian/vol-282/year-0939/part-01/sources/library/xintangshu-080-li-yi/source.txt", "note": "《新唐书》卷80·宗室·李祎附传，段落 xin-tangshu-685ef499825e-p026019；已核上下文及传主，纸本及异文待核。", "id": "58a4917e-6cb3-5c09-9239-b7012c664f10"}, {"title": "新唐书·卷80·宗室·李祎附传", "source_type": "primary", "author": "欧阳修、宋祁", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d0ce37b98c182cdb5c5cd2ee909baa3b407a4785/content/books/zizhi-tongjian/vol-282/year-0939/part-01/sources/library/xintangshu-080-li-yi-sons/source.txt", "note": "《新唐书》卷80·宗室·李祎附传，段落 xin-tangshu-685ef499825e-p026020；已核上下文及传主，纸本及异文待核。", "id": "354ba00b-1454-50ff-86ee-598357740132"}, {"title": "新五代史·卷62·南唐世家", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d0ce37b98c182cdb5c5cd2ee909baa3b407a4785/content/books/zizhi-tongjian/vol-282/year-0939/part-01/sources/library/xinwudaishi-062-ancestry/source.txt", "note": "《新五代史》卷62·南唐世家，段落 xin-wudaishi-b08f244b9241-p003130；已核上下文及传主，纸本及异文待核。", "id": "c6cff11d-bc6a-5175-9636-1cd1a10b48c4"}, {"title": "资治通鉴·后晋纪二", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7ab11539b383300ef1f618b97db115f4d85186a1/content/books/zizhi-tongjian/vol-281/year-0937/part-05/sources/library/tongjian-281-937-july-aftermath/source.txt", "note": "《资治通鉴》后晋纪二，段落 zizhi-tongjian-a63549944a71-p003343；电子底本待考，分段待核", "id": "cc007ffa-0d92-56e5-9c30-c70f558d191c"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "张从恩", "aliases": ["張從恩"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，曾任澶州防御使。939年正月任后晋枢密副使。生卒年未载。", "biography": null, "status": "draft", "id": "e1e909ad-c88c-54a5-941c-6116c704a870"}, {"name": "张希崇", "aliases": ["張希崇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成三年条所见人物：张希崇，藩汉都提举使、接任卢龙节度守平州者。", "biography": null, "status": "draft", "id": "dea611fa-916c-50fe-a044-c0c5fb5c23c6"}, {"name": "冯晖", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷263天复二年条所见人物：冯晖。", "biography": null, "status": "draft", "id": "e59e2b00-2873-5968-ab4c-938628164ecf"}, {"name": "拓跋彦超", "aliases": ["拓跋彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "党项首领。939年冯晖接任朔方节度使后，拓跋彦超前往祝贺，受到优待并被留在城中。生卒年未载。", "biography": null, "status": "draft", "id": "07cc4da4-56f5-51e9-b06f-b2b7fe597419"}, {"name": "徐知证", "aliases": ["徐知證"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐氏宗室。937年十月，徐诰即位后封他为江王。《新五代史》也记载这一封爵。", "biography": null, "status": "draft", "id": "4343d028-faf4-51b1-a2ef-c11390e12a40"}, {"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李昪。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "徐温", "aliases": ["徐溫"], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“张颢、徐温发动兵谏，控制淮南军政”中为事变组织者。", "biography": null, "status": "draft", "id": "d3682e36-8a8e-5558-8399-51a71c81330f"}, {"name": "宋氏（南唐李昪后）", "aliases": ["宋氏（李昪后）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李昪的皇后。937年被立为皇后，939年与李昪为李氏父母服丧。个人名字及生卒年本次未核。", "biography": null, "status": "draft", "id": "87d8df9d-227e-5ea6-9284-514b5a1aebcd"}, {"name": "徐知谔", "aliases": ["徐知諤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：徐知谔，润州团练使、被叙亲自交易者。", "biography": null, "status": "draft", "id": "ac076e03-0802-5e0f-9c3f-c1a717712543"}, {"name": "广德长公主（李建勋妻）", "aliases": ["广德长公主", "廣德長公主"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李建勋的妻子，封广德长公主。939年李昪为李氏父母服丧时，她借来丧服入内哭祭。个人名字及生卒年未载。", "biography": null, "status": "draft", "id": "a0a8594a-1a6e-5cd3-8dac-d21ea09a63f8"}, {"name": "李建勋", "aliases": ["李建勳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李建勋，节度副使、屡陈功业者。", "biography": null, "status": "draft", "id": "6b23676b-32be-5201-8ad3-171b7cc648e3"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "宋齐丘", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：宋齐丘。", "biography": null, "status": "draft", "id": "313ec6c3-7027-5fef-8b5d-b79d259f9c8a"}, {"name": "李恪（唐吴王）", "aliases": ["李恪", "吴王恪"], "era": "唐", "birth_year": null, "death_year": null, "description": "唐朝吴王。939年李昪选择追认他为祖先，并追尊为定宗孝静皇帝。《资治通鉴》说明相连世系部分出自官员编撰，不能据此确认李昪的远祖血缘。", "biography": null, "status": "draft", "id": "5ae9bca3-e4d2-5688-b670-077142bd82b7"}, {"name": "李祎（唐信安郡王）", "aliases": ["李祎（吴王孙）", "李祎（唐代宗室）"], "era": "唐", "birth_year": null, "death_year": null, "description": "唐代宗室。《新唐书》记他在开元年间改封信安郡王。939年南唐讨论祖系时提到吴王的孙子李祎及其子李岘。", "biography": null, "status": "draft", "id": "3a4f0021-58bf-56d2-85cb-74300755515d"}, {"name": "李岘（唐代宰相）", "aliases": ["李岘", "李峴"], "era": "唐", "birth_year": null, "death_year": null, "description": "唐代宰相，李祎的儿子。939年南唐官员讨论李昪祖系时提到他；李昪与他的后续世系被《资治通鉴》指出多由官员编撰。生卒年本次未核。", "biography": null, "status": "draft", "id": "c6ba5ba8-d120-5597-864e-cc4e5abde5bd"}, {"name": "李荣（李昪父）", "aliases": ["李荣", "李榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李昪的父亲。939年李昪恢复李姓并讨论宗庙祖系时，史书提到李荣。生卒年本次未核。", "biography": null, "status": "draft", "id": "c1122d1d-0122-59dd-bcf3-64a8048b189a"}, {"name": "卢损（后晋册礼使）", "aliases": ["卢损", "盧損"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋左散骑常侍。938年十一月受命为册礼使，参与后晋封王继鹏为闽国王的安排。生卒年未载。", "biography": null, "status": "draft", "id": "0c09b996-f1d4-5968-b303-4dd2f489cf1a"}, {"name": "王继鹏", "aliases": ["王繼鵬", "王昶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王继鹏，被任命权军府事的王子。", "biography": null, "status": "draft", "id": "94e0308c-1642-5beb-9233-76f848fff4f0"}, {"name": "王继恭", "aliases": ["王繼恭"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国官员，937年以威武节度使身份奉闽王命向后晋报告继位并请求设立邸舍。《资治通鉴》称他为闽王王继鹏的弟弟，《新五代史》称为儿子，亲属身份存在异说。", "biography": null, "status": "draft", "id": "10a53d6a-e6d8-5230-b1aa-76b1340b24f1"}, {"name": "郑元弼", "aliases": ["鄭元弼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国礼部员外郎。939年奉王继恭的表章，随卢损前往后晋进贡。生卒年未载。", "biography": null, "status": "draft", "id": "a656f099-5f42-574b-bfa0-daa89cb73913"}, {"name": "林省邹", "aliases": ["林省鄒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国士人。939年私下向卢损批评王继鹏的行为，表示计划扮作僧人向北逃走。是否实际逃走本段未载。", "biography": null, "status": "draft", "id": "93e9379f-865c-5b86-bee4-eb90509c2516"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "杜重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州人，后晋将领，妻子是石敬瑭的妹妹乐平长公主。937年以护圣都指挥使身份率军驻卫州。", "biography": null, "status": "draft", "id": "e5e23c10-447f-5238-bc56-f376300f9bac"}, {"name": "赵莹", "aliases": ["趙瑩"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：赵莹，劝赴任者。", "biography": null, "status": "draft", "id": "1f5a50e7-b046-593f-8be4-621934211b27"}, {"name": "和凝", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：和凝，翰林学士、建议者。", "biography": null, "status": "draft", "id": "f4084e8d-6018-5318-8498-525d067ebeda"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "石敬瑭任张从恩为枢密副使", "start_year": 939, "end_year": 939, "time_original": "939年正月辛亥", "dynasty": "五代十国", "description": "石敬瑭任张从恩为枢密副使。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "4ed72f51-a443-5b01-bb61-5751fbc660ea"}, {"title": "朔方节度使张希崇去世", "start_year": 939, "end_year": 939, "time_original": "939年正月条下，具体日期未载", "dynasty": "五代十国", "description": "朔方节度使张希崇去世。", "phases": [], "location_name": "朔方", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "de879b92-f2ab-5394-a965-21e29d54d30e"}, {"title": "张希崇去世后，朔方遭羌胡劫掠", "start_year": 939, "end_year": 939, "time_original": "939年正月条下，具体日期未载", "dynasty": "五代十国", "description": "张希崇去世后，史书所称羌胡在朔方劫掠，不再有所顾忌。", "phases": [], "location_name": "朔方", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "54a61974-7b85-554a-b87f-a21b7487ac77"}, {"title": "石敬瑭任冯晖为朔方节度使", "start_year": 939, "end_year": 939, "time_original": "939年正月甲寅", "dynasty": "五代十国", "description": "石敬瑭任冯晖为朔方节度使。", "phases": [], "location_name": "朔方", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c1b5e9bb-91b7-5f60-9c47-a405a3222456"}, {"title": "拓跋彦超前往祝贺冯晖，冯晖优待并将他留在城中", "start_year": 939, "end_year": 939, "time_original": "939年正月条下，具体日期未载", "dynasty": "五代十国", "description": "史书称拓跋彦超是势力最强的党项首领。冯晖到任后，拓跋彦超前往祝贺。冯晖优待他，在城中修建住宅、供给服饰器物，并留下他，不让他离去。", "phases": [], "location_name": "朔方", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "a99f9a41-999c-51ad-840e-eb50121e14d8"}, {"title": "史书记述冯晖留下拓跋彦超后，辖境恢复安定", "start_year": 939, "end_year": 939, "time_original": "939年正月条下，具体日期未载", "dynasty": "五代十国", "description": "史书记述冯晖留下拓跋彦超后，辖境恢复安定。", "phases": [], "location_name": "朔方", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "9c611188-7e1a-5cd1-9719-6e7c3f04aac5"}, {"title": "徐知证等多次请求李昪恢复李姓、建立唐朝宗庙", "start_year": 939, "end_year": 939, "time_original": "939年正月条下，具体日期未载", "dynasty": "五代十国", "description": "徐知证等多次请求李昪恢复李姓、建立唐朝宗庙。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c2ac4dc1-4f22-5c5c-88ad-c849f08960d6"}, {"title": "李昪批准恢复李姓和建立唐朝宗庙", "start_year": 939, "end_year": 939, "time_original": "939年正月乙丑", "dynasty": "五代十国", "description": "李昪批准恢复李姓和建立唐朝宗庙。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "fcf00fab-bfc0-52f8-ad77-cbec4642361b"}, {"title": "李昪拒绝群臣请求添加尊号", "start_year": 939, "end_year": 939, "time_original": "939年正月条下，具体日期未载", "dynasty": "五代十国", "description": "群臣请求为李昪添加尊号。李昪认为尊号只是虚美之辞，也不符合古制，因此拒绝接受。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "6f2b3c3d-f331-50f0-bb8e-1f109ad7e9e2"}, {"title": "史书记述南唐后代沿用不受尊号等做法", "start_year": null, "end_year": null, "time_original": "李昪之后子孙的追述，具体年月未载", "dynasty": "五代十国", "description": "《资治通鉴》记李昪后来的子孙继续不接受尊号，也不让外戚辅政、宦官参与政事，并评价这些做法优于其他国家。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "03e36cf2-0e38-586a-8d0f-c0d0c77ff59f"}, {"title": "李昪将徐温的庙号由太祖改为义祖", "start_year": 939, "end_year": 939, "time_original": "939年二月乙亥", "dynasty": "五代十国", "description": "李昪将徐温的庙号由太祖改为义祖。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "cb87fcc3-140c-565c-94be-233bc973df22"}, {"title": "李昪和皇后为李氏父母服丧，朝夕哭祭五十四天", "start_year": 939, "end_year": 939, "time_original": "939年二月己卯开始，朝夕哭祭五十四天", "dynasty": "五代十国", "description": "李昪为李氏父母发哀，与皇后穿斩衰丧服、居丧庐，按刚去世时的礼仪服丧，早晚哭祭，共五十四天。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "8b6094e1-ef98-58dd-826c-272d356223b5"}, {"title": "李昪拒绝徐知证和徐知谔一同服斩衰的请求", "start_year": 939, "end_year": 939, "time_original": "939年二月条下，具体日期未载", "dynasty": "五代十国", "description": "李昪拒绝徐知证和徐知谔一同服斩衰的请求。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "be8c5db9-1ded-516b-bfc1-32af0bd76b54"}, {"title": "广德长公主借来丧服，入内哭祭李氏父母", "start_year": 939, "end_year": 939, "time_original": "939年二月条下，具体日期未载", "dynasty": "五代十国", "description": "李建勋的妻子广德长公主借来丧服，入内尽情哭祭，表现得如同自己的父母去世。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "06cc068e-cae4-523a-8079-fa2f1ad23dab"}, {"title": "李昪命李璟处理国事，军事仍须报告", "start_year": 939, "end_year": 939, "time_original": "939年二月辛巳", "dynasty": "五代十国", "description": "李昪命李璟处理国事，军事仍须报告。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "5fe85b89-fe72-528f-b697-f8906a038b61"}, {"title": "李昪改用昪作为名字", "start_year": 939, "end_year": 939, "time_original": "939年二月庚寅", "dynasty": "五代十国", "description": "李昪改用昪作为名字。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "8b80090e-2277-52c3-bbce-ba0ec90d41bb"}, {"title": "李昪命百官讨论李氏与徐氏两套宗庙合祭礼仪", "start_year": 939, "end_year": 939, "time_original": "939年二月条下，具体日期未载", "dynasty": "五代十国", "description": "李昪命百官讨论李氏与徐氏两套宗庙合祭礼仪。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "08e55c3b-b251-5321-b422-330e3e06cf7d"}, {"title": "宋齐丘等提议将徐温安排在七室东侧", "start_year": 939, "end_year": 939, "time_original": "939年二月辛卯", "dynasty": "五代十国", "description": "宋齐丘等提议将徐温安排在七室东侧。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ac1449ac-0f4b-55cd-a394-822fe529c0a5"}, {"title": "李昪命唐高祖、唐太宗和徐温按次序设置不祧之主", "start_year": 939, "end_year": 939, "time_original": "939年二月条下，具体日期未载", "dynasty": "五代十国", "description": "李昪命唐高祖居西室，唐太宗次之，义祖徐温再次之，三者都作为不随世代迁除的祭祀对象。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "d8f38e4e-2df2-5fec-a240-25c2ceede151"}, {"title": "群臣提议另设徐温祠庙，李昪以受恩于徐温回应", "start_year": 939, "end_year": 939, "time_original": "939年二月条下，具体日期未载", "dynasty": "五代十国", "description": "群臣认为徐温原为诸侯，不应与唐高祖、唐太宗同享祭祀，建议在太庙正殿后另建庙。李昪强调自己自幼依托徐温，且徐温有功于吴，群臣随后不敢再议。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "968a17f0-de00-5543-8c4a-e1b31b475a03"}, {"title": "李昪打算追认吴王李恪为祖先，有人建议改认郑王", "start_year": 939, "end_year": 939, "time_original": "939年二月条下，具体日期未载", "dynasty": "五代十国", "description": "李昪打算追认吴王李恪为祖先。有人以李恪遭诛为由，建议改认郑王；所用《资治通鉴》电子本将这位郑王的名字写作“无懿”，仍待版本校核。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "1e42d5b2-3cd9-5855-bb94-605164d8704f"}, {"title": "李昪命官员考查祖系，选择吴王李恪并接受官员编写的世系", "start_year": 939, "end_year": 939, "time_original": "939年二月条下，具体日期未载", "dynasty": "五代十国", "description": "官员以吴王的孙子李祎有功、李祎之子李岘曾任宰相为依据，选择吴王李恪，称从李岘下传五世到李昪父亲李荣。《资治通鉴》指出，其中的名字大多由官员编撰。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "713d0144-59aa-5893-899b-e08ca1446ab3"}, {"title": "李昪质疑祖系代数，听取每三十年一代的解释后接受", "start_year": 939, "end_year": 939, "time_original": "939年二月条下，具体日期未载", "dynasty": "五代十国", "description": "李昪认为唐朝经历十九位皇帝、三百年，而所列十代祖系显得太少。官员以三十年为一代，并以李昪生于文德年间、距今约五十年来解释，李昪于是接受。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "27c1cfe5-9125-5478-a655-a26a535b38b7"}, {"title": "卢损到福州，王继鹏称病不见，命王继恭接待", "start_year": 939, "end_year": 939, "time_original": "939年二月条下，具体日期未载", "dynasty": "五代十国", "description": "卢损到福州，王继鹏称病不见，命王继恭接待。", "phases": [], "location_name": "福州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "92f8198d-4694-55bb-8a00-c8334bb268b7"}, {"title": "郑元弼奉王继恭表章，随卢损前往后晋进贡", "start_year": 939, "end_year": 939, "time_original": "939年二月条下，具体日期未载", "dynasty": "五代十国", "description": "郑元弼奉王继恭表章，随卢损前往后晋进贡。", "phases": [], "location_name": "福州、后晋", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "65a2e153-48ec-5b0e-a305-bf1a2e827e44"}, {"title": "林省邹私下批评王继鹏，并向卢损表示计划北逃", "start_year": 939, "end_year": 939, "time_original": "939年二月条下，具体日期未载", "dynasty": "五代十国", "description": "王继鹏对卢损失礼。林省邹私下向卢损批评王继鹏不敬君主、不爱亲人、不体恤百姓、不敬神祇、不睦邻、不礼宾客，认为他难以长久维持统治。林省邹表示计划穿僧服北逃，期待以后在后晋相见。", "phases": [], "location_name": "福州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "8ca6bd58-4b56-55cf-805a-3c2652892deb"}, {"title": "李昪追尊吴王李恪为定宗孝静皇帝", "start_year": 939, "end_year": 939, "time_original": "939年三月庚戌", "dynasty": "五代十国", "description": "李昪追尊吴王李恪为定宗孝静皇帝。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "0d6d526d-8b06-5e4e-8d4e-e35162b9cc74"}, {"title": "李昪为所认曾祖以下祖先追尊庙号和谥号", "start_year": 939, "end_year": 939, "time_original": "939年三月庚戌", "dynasty": "五代十国", "description": "李昪为所认曾祖以下祖先追尊庙号和谥号。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "64f1ca7c-83d3-5e28-b84f-3d09084f1b10"}, {"title": "石敬瑭同时给刘知远、杜重威加同平章事", "start_year": 939, "end_year": 939, "time_original": "939年三月己未", "dynasty": "五代十国", "description": "石敬瑭同时给刘知远、杜重威加同平章事。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "2b12e767-335e-56ca-a317-017b2c7e00c8"}, {"title": "刘知远不愿与杜重威同受任命，闭门四次上表推辞", "start_year": 939, "end_year": 939, "time_original": "939年三月条下，具体日期未载", "dynasty": "五代十国", "description": "刘知远认为自己有扶立石敬瑭的功劳，而杜重威主要凭外戚身份起用、没有大功，不愿与他同受任命。诏令下达几天后，刘知远闭门，四次上表推辞。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e718365d-d541-51de-9d98-7fe161c55d9a"}, {"title": "石敬瑭因刘知远拒命发怒，提出解除其军权", "start_year": 939, "end_year": 939, "time_original": "939年三月条下，具体日期未载", "dynasty": "五代十国", "description": "石敬瑭发怒，向赵莹强调杜重威是自己的妹夫，责问刘知远为何坚拒诏令，并提出解除刘知远军权、让他回私人住宅。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "027a4b7c-40b8-53a2-96b5-51a07947683a"}, {"title": "赵莹以晋阳起兵时的功劳劝石敬瑭宽容刘知远", "start_year": 939, "end_year": 939, "time_original": "939年三月条下，具体日期未载", "dynasty": "五代十国", "description": "赵莹提到石敬瑭在晋阳只有约五千兵、面对十余万唐军时，刘知远坚定相助，认为不应因小过弃用他，也担忧这些话传出去影响皇帝宽容的形象。石敬瑭听后怒意缓解。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "8bb6e7a9-82de-5d89-b739-06aa28e7fcb8"}, {"title": "和凝奉命到刘知远家传达旨意，刘知远接受任命", "start_year": 939, "end_year": 939, "time_original": "939年三月条下，具体日期未载", "dynasty": "五代十国", "description": "和凝奉命到刘知远家传达旨意，刘知远接受任命。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "bc8b7edc-e0fa-5ee4-a6d9-0c906321ea22"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

